import{_ as s,C as r,o,c as i,ah as a,E as n}from"./chunks/framework.CRgxdAhU.js";const y=JSON.parse('{"title":"Schemas first, and a dictionary that writes itself","description":"","frontmatter":{"title":"Schemas first, and a dictionary that writes itself","date":"2026-10-24T00:00:00.000Z","phase":0,"status":"work-in-progress"},"headers":[],"relativePath":"blog/schemas-and-data-dictionary.md","filePath":"blog/schemas-and-data-dictionary.md"}'),d={name:"blog/schemas-and-data-dictionary.md"};function h(c,e,l,m,p,f){const t=r("Mermaid");return o(),i("div",null,[e[0]||(e[0]=a('<h1 id="schemas-first-and-a-dictionary-that-writes-itself" tabindex="-1">Schemas first, and a dictionary that writes itself <a class="header-anchor" href="#schemas-first-and-a-dictionary-that-writes-itself" aria-label="Permalink to &quot;Schemas first, and a dictionary that writes itself&quot;">​</a></h1><p>Everything a WRX1 game stores lives in the XMPP server as JSON documents: the game setup, each force, role and room, objectives, theme images, announcements, and the body of every chat message. Before writing any transport, mock or UI, we wrote down the shape of every one of those documents as a runtime schema. This post explains why, and how the <a href="./../data-dictionary.html">data dictionary</a> on this site is generated from them.</p><h2 id="why-schemas-come-first" tabindex="-1">Why schemas come first <a class="header-anchor" href="#why-schemas-come-first" aria-label="Permalink to &quot;Why schemas come first&quot;">​</a></h2><p>Three parts of WRX1 read and write the same documents: the admin backend that publishes a game, the player client that reads it, and the in-browser mock server used for demos. If each had its own idea of what a room looks like, they would drift apart, and a demo on the mock would stop being a fair picture of the real server.</p><p>So there is one source of truth, <code>packages/schemas</code>, built with <a href="https://zod.dev" target="_blank" rel="noreferrer">zod</a>. Each schema both <strong>validates</strong> data at runtime and <strong>defines</strong> the TypeScript type, which is inferred from it. A field can&#39;t be added to the type without being added to the validation, or the other way round.</p>',5)),n(t,{code:"flowchart%20LR%0A%20%20%20%20schema%5B%22zod%20schema%22%5D%20--%3E%20type%5B%22TypeScript%20type%22%5D%0A%20%20%20%20schema%20--%3E%20parse%5B%22parseDocument%3A%20validate%20and%20migrate%22%5D%0A%20%20%20%20schema%20--%3E%20dictionary%5B%22Data%20dictionary%22%5D%0A%20%20%20%20type%20--%3E%20admin%5B%22Admin%20backend%22%5D%0A%20%20%20%20type%20--%3E%20player%5B%22Player%20client%22%5D%0A%20%20%20%20type%20--%3E%20mock%5B%22Mock%20server%22%5D%0A%20%20%20%20parse%20--%3E%20admin%20%26%20player%20%26%20mock%0A"}),e[1]||(e[1]=a('<h2 id="every-document-carries-a-version" tabindex="-1">Every document carries a version <a class="header-anchor" href="#every-document-carries-a-version" aria-label="Permalink to &quot;Every document carries a version&quot;">​</a></h2><p>Each document has a <code>schemaVersion</code>. When a client reads one, <code>parseDocument</code> migrates older versions forward one step at a time and then validates the result. It never throws: a document that fails validation comes back as a typed error, which the caller logs and ignores, so one bad document can&#39;t crash a player&#39;s screen. The same result type is the convention for both transport layers.</p><h2 id="rules-the-schemas-enforce" tabindex="-1">Rules the schemas enforce <a class="header-anchor" href="#rules-the-schemas-enforce" aria-label="Permalink to &quot;Rules the schemas enforce&quot;">​</a></h2><p>Some of the design rules are easier to enforce in a schema than to remember in code review:</p><ul><li><strong>Ids are stable slugs.</strong> Forces, roles, rooms and assets get lower-case, URL-safe ids that never change, and display names are separate fields.</li><li><strong>No passwords in documents.</strong> Role passwords are never stored in a PubSub document, and the design export file rejects a <code>password</code> field outright, so a design that carries passwords can&#39;t be imported.</li><li><strong>Sizes are checked before publishing.</strong> Theme images default to a 100 KB limit, and every document is checked against the server&#39;s PubSub item limit before it is sent.</li><li><strong>Cross-document checks.</strong> A whole design is checked for unique ids, references that resolve, and at most one umpire force.</li></ul><h2 id="a-dictionary-that-writes-itself" tabindex="-1">A dictionary that writes itself <a class="header-anchor" href="#a-dictionary-that-writes-itself" aria-label="Permalink to &quot;A dictionary that writes itself&quot;">​</a></h2><p>The schemas carry descriptions, and a small generator walks them to produce Markdown: one table per document, with every field&#39;s type, whether it is required, its constraints and its description. That file, <code>docs/data-dictionary.md</code>, is committed to the repo, and CI fails if it is out of date with the schemas.</p><p>This site doesn&#39;t copy it either. The data dictionary page includes the generated file when the site is built, so the published dictionary always matches the code it was built from.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>The schemas are a frozen interface from here on: later changes are allowed, but each one is listed at the phase gate. Phase 1 builds on them with the transport interface, the contract test suite and the mock server.</p>',10))])}const w=s(d,[["render",h]]);export{y as __pageData,w as default};
